#requires -Version 5.1
$ErrorActionPreference='Stop';. (Join-Path (Split-Path $PSScriptRoot -Parent) 'src\Connectivity.ps1')
function Parse($text){$s=[IO.MemoryStream]::new([Text.Encoding]::ASCII.GetBytes($text));try{Read-ProbeHttpStatus $s ([Diagnostics.Stopwatch]::StartNew()) 1000}finally{$s.Dispose()}}
foreach($case in @(@("HTTP/1.1 103 Early Hints`r`nLink: </a>`r`n`r`nHTTP/1.1 200 OK`r`n`r`n",'Success'),@("HTTP/1.1 100 Continue`r`n`r`nHTTP/1.1 103 Early Hints`r`n`r`nHTTP/1.1 503 Unavailable`r`n`r`n",'HttpError'))){if((Get-ProbeHttpOutcome (Parse $case[0])) -ne $case[1]){throw 'Wrong final outcome'}}
foreach($text in @("HTTP/1.1 103 Early Hints`r`n`r`n", "HTTP/1.1 200 OK`r`nX: truncated", "HTTP/1.1 999 Bad`r`n`r`n", "HTTP/1.1 2000 Bad`r`n`r`n", "HTTP/1.1 101 Upgrade`r`n`r`n", (("HTTP/1.1 103 Hint`r`n`r`n"*9)+"HTTP/1.1 200 OK`r`n`r`n"), ("HTTP/1.1 200 OK`r`nX: "+('a'*4097)+"`r`n`r`n"), ("HTTP/1.1 200 OK`r`n"+(("X: "+('a'*4000)+"`r`n")*9)+"`r`n"))){$failed=$false;try{$null=Parse $text}catch{$failed=$true};if(-not $failed){throw 'Malformed/truncated/over-limit response accepted'}}
$e=[pscustomobject]@{InformationalStatuses=@();HttpStatusLine=$null;FinalStatusCode=$null};$s=[IO.MemoryStream]::new([Text.Encoding]::ASCII.GetBytes("HTTP/1.1 103 Hint`r`n`r`n"));try{$null=Read-ProbeHttpStatus $s ([Diagnostics.Stopwatch]::StartNew()) 1000 $e}catch{}finally{$s.Dispose()};if($e.InformationalStatuses.Count -ne 1 -or $null -ne $e.FinalStatusCode){throw 'Partial status evidence lost'}
$s=[IO.MemoryStream]::new();$expired=$false;try{$null=Read-ProbeHttpStatus $s ([Diagnostics.Stopwatch]::StartNew()) 0}catch{$expired=$_.Exception -is [TimeoutException]}finally{$s.Dispose()};if(-not $expired){throw 'Overall timeout not enforced'}
Write-Host 'PASS: bounded synthetic HTTP streams, informational/final status, malformed/EOF/limits/timeout; no sockets.'
